const order = ['^GSPC','^IXIC','^DJI','^RUT','^FTSE','^N225','^HSI','^STI'];
const nameMap = {
  '^GSPC': 'S&P 500',
  '^IXIC': 'Nasdaq Composite',
  '^DJI': 'Dow Jones Industrial Average',
  '^RUT': 'Russell 2000',
  '^FTSE': 'FTSE 100',
  '^N225': 'Nikkei 225',
  '^HSI': 'Hang Seng',
  '^STI': 'Straits Times Index (STI)'
};
const bySymbol = {};
for (const it of $input.all()) {
  const res = it.json && it.json.chart && it.json.chart.result && it.json.chart.result[0];
  if (!res || !res.meta) continue;
  const meta = res.meta;
  const sym = meta.symbol;
  let latest = typeof meta.regularMarketPrice === 'number' ? meta.regularMarketPrice : null;
  const chg = typeof meta.regularMarketChangePercent === 'number' ? meta.regularMarketChangePercent : null;
  try {
    const closes = (res.indicators.quote[0].close || []).filter(v => typeof v === 'number');
    if (latest === null && closes.length) latest = closes[closes.length - 1];
  } catch (e) {}
  bySymbol[sym] = { latest, chg, currency: meta.currency || '' };
}
const lines = [];
const indices = [];
for (const sym of order) {
  const name = nameMap[sym];
  const d = bySymbol[sym];
  if (!d || d.latest === null) { lines.push('- ' + name + ': data unavailable'); continue; }
  const chg = typeof d.chg === 'number' ? d.chg : null;
  const arrow = chg === null ? '' : (chg >= 0 ? '▲' : '▼');
  const closeStr = d.latest.toLocaleString('en-US', { maximumFractionDigits: 2 });
  const chgStr = chg === null ? 'n/a' : (arrow + ' ' + Math.abs(chg).toFixed(2) + '%');
  lines.push('- ' + name + ': ' + closeStr + ' (' + chgStr + ')');
  indices.push({ symbol: sym, name, latest: d.latest, changePct: chg });
}
return [{ json: { indicesText: lines.join('\n'), indices } }];

const items = $input.all().slice(0, 6);
const lines = items
  .map(it => '- ' + String((it.json && it.json.title) || '').trim())
  .filter(l => l.length > 2);
const headlinesText = lines.length ? lines.join('\n') : '- No headlines available';
return [{ json: { headlinesText } }];

const md = String($json.output || "");
function esc(s) {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
}
const lines = md.split(/\r?\n/);
let html = "";
let inList = false;
for (const raw of lines) {
  let line = raw.trim();
  const isBullet = line.startsWith("- ");
  if (isBullet) {
    if (!inList) { html += "<ul>"; inList = true; }
    line = line.slice(2);
  } else if (inList) {
    html += "</ul>";
    inList = false;
  }
  let content = esc(line);
  content = content.replace(/\*([^*]+)\*/g, "<strong>$1</strong>");
  if (isBullet) {
    html += "<li>" + content + "</li>";
  } else if (line === "") {
    html += "<br>";
  } else {
    html += "<p style=\"margin:0 0 10px 0;\">" + content + "</p>";
  }
}
if (inList) html += "</ul>";
const wrapped = "<div style=\"font-family:Arial,Helvetica,sans-serif;font-size:14px;line-height:1.5;color:#222;\">" + html + "</div>";
return [{ json: { html: wrapped, output: md } }];
